export default function TaskInterface({task, act}) {
  const t = task || {};
  const m = t.merchant || {};
  const intent = t.intent || {};
  const [choices, setChoices] = React.useState({});
  const [changedMethod, setChangedMethod] = React.useState(false);
  const arr = v => Array.isArray(v) ? v : [];
  const show = v => v == null || v === '' ? 'Unknown' : typeof v === 'object' ? JSON.stringify(v) : String(v);
  const names = {original_payment:'Original payment method',store_credit:'Store credit',qr_dropoff:'Printer-free QR drop-off',print_label:'Print a shipping label'};
  const nameOf = v => names[v] || show(v);
  const amount = v => {
    if (typeof v !== 'number' || !Number.isFinite(v) || !m.currency) return 'Unknown';
    try { return new Intl.NumberFormat('en-US',{style:'currency',currency:m.currency}).format(v/100); } catch (err) { return 'Unknown currency'; }
  };
  const initial = !task || t.status === 'not_started';
  const busy = !!t.progress || ['working','created','submitting'].includes(t.status);
  const locked = initial || busy || !!t.receipt || typeof act !== 'function';
  const methods = arr(m.methods).filter(x => x && ['print_label','qr_dropoff'].includes(x.value));
  const reasons = arr(m.reasons).filter(x => x && x.value);
  const lines = arr(m.lines).filter(Boolean);
  const selected = Array.isArray(m.selectedLines) ? m.selectedLines.map(x => x && typeof x === 'object' ? x.id : x) : null;
  const isShoe = x => /red.*shoe|shoe.*red/i.test((x.name || '') + ' ' + (x.variant || ''));
  const shoeLines = lines.filter(isShoe);
  const methodChoice = choices.method || m.method || '';
  const reasonChoice = choices.reason !== undefined ? choices.reason : t.reason || '';
  const destinationIntent = intent.refundDestination || 'original_payment';
  const noPrinter = intent.noPrinter !== false;
  const failedChecks = arr(t.checks).filter(c => c && (['fail','failed','conflict','mismatch','error'].includes(c.status) || (c.expected !== undefined && c.observed !== undefined && JSON.stringify(c.expected) !== JSON.stringify(c.observed))));
  const destinationConflict = !!m.refundDestination && m.refundDestination !== destinationIntent;
  const methodConflict = !!m.method && ((choices.method && choices.method !== m.method) || (noPrinter && m.method === 'print_label'));
  const reasonConflict = choices.reason && t.reason && choices.reason !== t.reason;
  const itemConflict = selected !== null && (selected.some(id => !shoeLines.some(x => x.id === id)) || (shoeLines.length > 0 && shoeLines.some(x => !selected.includes(x.id))));
  const conflict = destinationConflict || methodConflict || reasonConflict || itemConflict || failedChecks.length > 0;
  const unknown = !m.method || !m.refundDestination || selected === null || !lines.length || !shoeLines.length || typeof m.deductionCents !== 'number' || typeof m.expectedRefundCents !== 'number' || !m.currency || !t.reason;
  const choose = (key,value) => {
    if (locked || !value) return;
    setChoices(prev => ({...prev,[key]:value}));
    if (key === 'method') setChangedMethod(true);
    act('choice',{[key]:value});
  };
  const check = repair => { if (!locked) act('check',{repair}); };
  const discovery = t.discovery || {};
  const fallbackScreens = [
    {id:'home',name:'Your next chapter, outside.'},
    {id:'orders',name:'Your orders'},
    {id:'shop',name:'Shop the collection'}
  ];
  const fallbackFlows = [
    {name:'My orders',exit:'orders',status:'verified'},
    {name:'View orders & delivery',exit:'home',status:'verified'},
    {name:'View product & options →',exit:'home',status:'verified'},
    {name:'Browse all products',exit:'shop',status:'verified'}
  ];
  const screens = arr(discovery.screens).length ? discovery.screens : fallbackScreens;
  const flows = arr(discovery.flows).length ? discovery.flows : fallbackFlows;
  const orderedFlows = [...flows].sort((a,b) => Number(/return|order/i.test(b.name || '')) - Number(/return|order/i.test(a.name || '')));
  const statusCopy = t.receipt ? 'A receipt is available from the host. Review its separate saved-confirmation verification; editing is disabled.' : busy ? 'The host is updating the task. Controls are temporarily unavailable.' : t.error ? 'An error needs attention. No completed return is claimed.' : initial ? 'Not started. Review this overview, then use the host’s Start this task control.' : conflict ? 'Your requested choices and the observed source differ. Restore your choices, then validate.' : unknown ? 'Some current terms are unknown. Validate to check the source before exact approval.' : 'Review the current terms, then validate. Validation does not submit your return.';
  const methodDetail = methods.find(x => x.value === methodChoice);
  return <main className="generated-root">
    <header className="generated-header"><strong>Northstar Outfitters</strong><span>Synthetic records · Sandbox only</span></header>
    <div className="generated-content">
      <p className="generated-eyebrow">Your return, on your terms</p>
      <h1>Return the red shoes.<br/>Keep the jacket.</h1>
      <p className="generated-intro">A printer-free return, with your refund preference kept on original payment.</p>
      <section className="generated-status" role="status" aria-live="polite" aria-atomic="true"><strong>{initial ? 'Task overview' : 'Live task status'}</strong><p>{statusCopy}</p>{t.status && <span className="generated-small">Host state: {show(t.status)}</span>}</section>
      {t.error && <section className="generated-warning" role="alert"><h2>Task error</h2><p>{show(t.error)}</p></section>}
      {initial ? <>
        <section className="generated-panel"><p className="generated-eyebrow">Supported task</p><h2>Only the shoes are going back</h2><ul className="generated-goals"><li>Return only the red shoes.</li><li>Keep jacket — never add it to the return.</li><li>Use a printer-free method.</li><li>Refund the original payment method.</li></ul><p>The host provides <strong>Start this task</strong> for this supported synthetic return. You will review the exact current terms separately before submission.</p></section>
        <section className="generated-panel"><h2>Two observed draft routes</h2><div className="generated-routes"><section className="generated-route"><span className="generated-tag">Relevant to your goal</span><h3>Printer-free QR drop-off</h3><p>Reached a saved draft with only the shoes selected and the jacket kept. This method has a deduction.</p><p><strong>Observed conflict:</strong> choosing QR drop-off changed the destination to store credit, despite an earlier original-payment choice.</p></section><section className="generated-route"><span className="generated-tag">Requires a printer</span><h3>Print a shipping label</h3><p>Reached a saved draft with only the shoes selected, the jacket kept and original payment selected.</p><p>This route requires printing and attaching a label, so it does not fit your no-printer request.</p></section></div><p className="generated-note">Changing a method can change the source refund destination. Your preference stays original payment. Review and restore any conflict before proceeding.</p><p className="generated-small">Live task data will supply current fees and refund amounts. These observations establish draft behavior, not a completed return or a verified saved confirmation.</p></section>
        <section className="generated-panel"><h2>Other observed routes</h2><p>Order-related routes are listed first. Reached-state labels matter more than route names; these cards are informational only.</p><div className="generated-routes">{orderedFlows.map((f,i) => {
          const reached = f.currentObservation?.reached || f.exit;
          const screen = screens.find(s => s.id === reached);
          return <section className="generated-route" key={f.id || i}><h3>{show(f.name)}</h3><p><strong>Reached:</strong> {screen ? show(screen.name) : 'Unknown reached screen'}</p><p className="generated-small">Recorded status: {show(f.status)}. No execution control.</p></section>;
        })}</div><p className="generated-small">The initial exploration ended at its budget limit. The red-shoes product path was not reached, and a source exception was recorded. The separate return-draft observations above do not establish completion.</p></section>
      </> : <>
        <div className="generated-grid"><div>
          <section className="generated-panel"><p className="generated-eyebrow">01 · Items</p><h2>Your requested scope</h2><div className="generated-scope"><strong>Return only red shoes</strong><span>Keep jacket</span></div><p className="generated-small">Requested scope is not editable here. The current source selection is shown separately below.</p>{lines.length ? <ul className="generated-items">{lines.map((line,i) => <li key={line.id || i}><strong>{show(line.name)}</strong>{line.variant && <p className="generated-small">{show(line.variant)}</p>}<p>Observed source: <strong>{selected === null ? 'Unknown selection' : selected.includes(line.id) ? 'Included in return' : 'Not included in return'}</strong></p>{/jacket/i.test(line.name || '') && <span className="generated-tag">Keep jacket · requested</span>}</li>)}</ul> : <p>Current source items: Unknown.</p>}{selected !== null && <p className="generated-small">Selected line IDs: {selected.length ? selected.map(show).join(', ') : 'None'}</p>}</section>
          <section className="generated-panel"><p className="generated-eyebrow">02 · Choices</p><h2>How to return the shoes</h2><div className="generated-field"><label htmlFor="generated-reason">Return reason</label><select id="generated-reason" value={reasonChoice} disabled={locked || !reasons.length} onChange={e => choose('reason',e.target.value)}><option value="">Choose a reason</option>{reasonChoice && !reasons.some(x => x.value === reasonChoice) && <option value={reasonChoice}>{show(reasonChoice)}</option>}{reasons.map(r => <option key={r.value} value={r.value}>{r.label || r.value}</option>)}</select><p className="generated-small">Observed reason: {reasons.find(r => r.value === t.reason)?.label || show(t.reason)}</p>{!reasons.length && <p className="generated-small">Available reasons are unknown.</p>}</div>
          <div className="generated-field"><label htmlFor="generated-method">Return method</label><select id="generated-method" value={methodChoice} disabled={locked || !methods.length} onChange={e => choose('method',e.target.value)}><option value="">Choose a method</option>{methodChoice && !methods.some(x => x.value === methodChoice) && <option value={methodChoice}>{nameOf(methodChoice)}</option>}{methods.map(x => <option key={x.value} value={x.value}>{x.label || nameOf(x.value)}</option>)}</select><p className="generated-small">Selected choice: {nameOf(methodChoice)}</p><p className="generated-small">Observed source method: {nameOf(m.method)}</p>{methodDetail?.detail && <p className="generated-small">{show(methodDetail.detail)}</p>}{!methods.length && <p className="generated-small">Available methods are unknown.</p>}</div>
          <p className="generated-note">Method changes can alter the refund destination in the source. They do not change your refund preference.</p>{changedMethod && <p className="generated-warning generated-inline">Method changed. Review the source deduction and destination, then validate again.</p>}<div className="generated-preference"><strong>Your refund preference</strong><p>{nameOf(destinationIntent)}</p><span className="generated-small">Requested intent, not the source’s current destination.</span></div></section>
        </div><section className="generated-panel generated-review"><p className="generated-eyebrow">03 · Source review</p><h2>Current return terms</h2><p className="generated-small">Authoritative current task data. Not a completed return.</p><dl className="generated-terms"><div><dt>Observed return method</dt><dd>{nameOf(m.method)}</dd></div><div><dt>Method fee / deduction</dt><dd>{amount(m.deductionCents)}</dd></div><div><dt>Observed refund destination</dt><dd>{nameOf(m.refundDestination)}</dd></div><div className="generated-total"><dt>Expected refund</dt><dd>{amount(m.expectedRefundCents)}</dd></div></dl>{unknown && <p className="generated-warning generated-inline">Some required choices or source terms are unknown. They must be established before dependent approval or completion.</p>}<p className="generated-small">Synthetic records only. No real shipment, QR code or refund is created.</p></section></div>
        {conflict && <section className="generated-warning" role="alert"><h2>Source conflict</h2>{destinationConflict && <p><strong>Requested refund:</strong> {nameOf(destinationIntent)}<br/><strong>Observed destination:</strong> {nameOf(m.refundDestination)}</p>}{methodConflict && <p><strong>Requested method:</strong> {choices.method ? nameOf(choices.method) : 'Printer-free return'}{noPrinter && choices.method === 'print_label' ? ' — conflicts with your no-printer goal' : ''}<br/><strong>Observed method:</strong> {nameOf(m.method)}</p>}{reasonConflict && <p><strong>Selected reason:</strong> {show(choices.reason)}<br/><strong>Observed reason:</strong> {show(t.reason)}</p>}{itemConflict && <p><strong>Requested items:</strong> only red shoes; keep jacket.<br/><strong>Observed selected IDs:</strong> {selected.length ? selected.map(show).join(', ') : 'None'}</p>}{failedChecks.length > 0 && <p>Source checks also report differences. See the requested and observed values below.</p>}<p>Restore reapplies your choices. It does not submit the return.</p><button type="button" className="generated-secondary" disabled={locked} onClick={() => check(true)}>Restore my choices</button></section>}
        <section className="generated-panel"><h2>Validate before exact approval</h2><p>Check the items, printer-free method, deduction and original-payment destination. The trusted host handles exact approval and separately verifies the saved confirmation.</p>{arr(t.checks).length > 0 && <ul className="generated-checks">{arr(t.checks).filter(Boolean).map((c,i) => <li key={i}><strong>{show(c.label)}</strong><span className="generated-tag">{show(c.status)}</span><p>Expected: {show(c.expected)}<br/>Observed: {show(c.observed)}</p></li>)}</ul>}<div className="generated-actions"><button type="button" className="generated-primary" disabled={locked} onClick={() => check(false)}>Validate current choices</button>{!conflict && <button type="button" className="generated-secondary" disabled={locked} onClick={() => check(true)}>Restore my choices</button>}</div><p className="generated-small">Validation is not submission. A saved draft is not a completed return.</p></section>
        {t.receipt && <section className="generated-panel"><h2>Receipt available from the host</h2><p>Review the host’s final receipt and independent saved-confirmation result for the outcome. Editing and validation are disabled.</p></section>}
      </>}
      <footer className="generated-footer">Sandbox · No production access · Exact approval and final confirmation remain with the trusted host.</footer>
    </div>
  </main>;
}
